            raise ValueError(f"backwards range {text!r}")
    else:
        first = _value(base, field, True)
        last = high if slash else first
    for value in range(first, last + 1, step):
        values.add(value % 7 if field == 4 else value)


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError(f"bad expression {expr!r}")
    text = expr.strip()
    if text.startswith("@"):
        try:
            text = _SHORTCUTS[text.lower()]
        except KeyError:
            raise ValueError(f"unknown shortcut {expr!r}") from None
    parts = re.split(r"[ \t]+", text)
    if len(parts) != 5:
        raise ValueError(f"expected 5 fields in {expr!r}")
    sets = []
    extras = {"last_day": False, "last_weekdays": set(), "nth_weekdays": set()}
    for field, part in enumerate(parts):
        values = set()
        if part == "?":
            if field not in (2, 4):
                raise ValueError(f"'?' not allowed in {part!r}")
            part = "*"
        for item in part.split(","):
            _item(item, field, values, extras)
        sets.append(values)
    return _Schedule(
        sets[0], sets[1], sets[2], sets[3], sets[4],
        extras["last_day"], extras["last_weekdays"], extras["nth_weekdays"],
        parts[2] not in ("*", "?"), parts[4] not in ("*", "?"),
    )


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    return _parse(expr).matches(when)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _parse(expr)
    try:
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + _LIMIT
    except OverflowError:
        limit = datetime.datetime.max
    day = start.date()
    first_day = True
    while True:
        if schedule.day_ok(day):
            for hour in schedule.hours:
                if first_day and hour < start.hour:
                    continue
                for minute in schedule.minutes:
                    if first_day and hour == start.hour and minute < start.minute:
                        continue
                    run = datetime.datetime(day.year, day.month, day.day, hour, minute)
                    return run if run <= limit else None
        first_day = False
        if day >= limit.date():
            return None
        day += datetime.timedelta(days=1)
